    }));
    assert!(seen.iter().any(|request| {
        request.uri == "/v1/conversations/conv.%3Fopaque/items?after=item_0&limit=20&order=desc"
    }));
    assert!(seen.iter().any(|request| {
        request.method == Method::PATCH && request.body == br#"{"metadata":{"updated":"yes"}}"#
    }));
